CREATE TABLE shipping_rates(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,region TEXT NOT NULL DEFAULT '',province TEXT NOT NULL DEFAULT '',city TEXT NOT NULL DEFAULT '',rate INTEGER NOT NULL CHECK(rate>=0),active INTEGER NOT NULL DEFAULT 1,cod_allowed INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_shipping_active ON shipping_rates(active,province,city);
CREATE TABLE reseller_inquiries(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL,mobile TEXT NOT NULL,location TEXT NOT NULL,facebook TEXT NOT NULL DEFAULT '',message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'New',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_reseller_status ON reseller_inquiries(status,created_at);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,admin_id INTEGER REFERENCES admins(id),action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,metadata TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_audit_time ON audit_logs(created_at);
ALTER TABLE orders ADD COLUMN region TEXT NOT NULL DEFAULT '';
ALTER TABLE orders ADD COLUMN shipping_zone TEXT NOT NULL DEFAULT '';
ALTER TABLE orders ADD COLUMN courier TEXT NOT NULL DEFAULT '';
ALTER TABLE orders ADD COLUMN tracking_number TEXT NOT NULL DEFAULT '';
